import pytest
from mcp.cli.limits import format_limits_table
from mcp.server.mcpserver.limits import LimitPolicy, Quota, RateLimit


def test_format_empty_list_returns_empty_string():
    assert format_limits_table([]) == ""


def test_format_tool_with_none_policy():
    assert format_limits_table([("echo", None)]) == "echo  rate=-  quota=-  scope=server"


def test_format_tool_with_default_limit_policy():
    assert format_limits_table([("echo", LimitPolicy())]) == "echo  rate=-  quota=-  scope=server"


def test_format_tool_with_empty_policy_session_scope():
    assert format_limits_table([("echo", LimitPolicy(scope="session"))]) == "echo  rate=-  quota=-  scope=session"


def test_format_rate_limit_whole_seconds_60():
    policy = LimitPolicy(rate_limit=RateLimit(max_calls=5, per_seconds=60.0))
    assert format_limits_table([("search", policy)]) == "search  rate=5/60s  quota=-  scope=server"


def test_format_rate_limit_whole_seconds_1():
    policy = LimitPolicy(rate_limit=RateLimit(max_calls=10, per_seconds=1.0))
    assert format_limits_table([("fetch", policy)]) == "fetch  rate=10/1s  quota=-  scope=server"


def test_format_rate_limit_fractional_seconds_half():
    policy = LimitPolicy(rate_limit=RateLimit(max_calls=2, per_seconds=0.5))
    assert format_limits_table([("ping", policy)]) == "ping  rate=2/0.5s  quota=-  scope=server"


def test_format_rate_limit_fractional_seconds_quarter():
    policy = LimitPolicy(rate_limit=RateLimit(max_calls=3, per_seconds=1.25))
    assert format_limits_table([("stream", policy)]) == "stream  rate=3/1.25s  quota=-  scope=server"


def test_format_quota_without_rate_limit():
    policy = LimitPolicy(quota=Quota(max_calls=100))
    assert format_limits_table([("compute", policy)]) == "compute  rate=-  quota=100  scope=server"


def test_format_spec_example_search_and_echo():
    tools = [
        ("search", LimitPolicy(rate_limit=RateLimit(max_calls=5, per_seconds=60), quota=Quota(max_calls=100), scope="session")),
        ("echo", None),
    ]
    assert format_limits_table(tools) == "search  rate=5/60s  quota=100  scope=session\necho  rate=-  quota=-  scope=server"


def test_format_preserves_input_order():
    tools = [("second", None), ("first", None), ("third", None)]
    assert format_limits_table(tools) == "second  rate=-  quota=-  scope=server\nfirst  rate=-  quota=-  scope=server\nthird  rate=-  quota=-  scope=server"


def test_format_two_spaces_between_fields():
    assert format_limits_table([("ping", None)]).split("  ") == ["ping", "rate=-", "quota=-", "scope=server"]
